import { createHash } from 'node:crypto';
import type { IncomingMessage, ServerResponse } from 'node:http';

// The demo's boot fixture seeds every random source, so a random draw here would shift the values
// the app generates after it. This id comes from a per-process counter run through sha256, so it
// draws nothing from the seeded stream and carries no user data.
let requestCount = 0;

function requestId(): string {
  const digest = createHash('sha256').update('x-request-id').update(String(requestCount++)).digest();
  const bytes = Buffer.from(digest.subarray(0, 16));
  bytes[6] = (bytes[6] & 0x0f) | 0x40;
  bytes[8] = (bytes[8] & 0x3f) | 0x80;
  const hex = bytes.toString('hex');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

