/**
 * A fixed window per key: the first `limit` calls in a window are allowed and the rest are denied
 * until the window ends. Every call counts, whether or not its request then succeeds. A key's
 * window opens at its first call, and the clock is read on every call.
 */
export function createWindowLimiter(limit: number, windowMs: number, now: () => number = () => Date.now()): RateLimiter {
  const windows = new Map<string, { start: number; count: number }>();
  return {
    check(key) {
      const at = now();
      let window = windows.get(key);
      if (window === undefined || at - window.start >= windowMs) {
        window = { start: at, count: 0 };
        windows.set(key, window);
      }
      window.count += 1;
      if (window.count <= limit) return { allowed: true, retryAfterSeconds: 0 };
      return { allowed: false, retryAfterSeconds: (window.start + windowMs - at) / 1000 };
    },
  };
}

